    gitBranch: raw.git.branch,
    gitWorktree: raw.git.worktree,
    added: raw.git.added,
    modified: raw.git.modified,
    deleted: raw.git.deleted,
    ctxTokens: u.ctxTokens,
    ctxPct: u.ctxPct,
